import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`restoration-estimate`,heroTitle:`Build restoration estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded damage reports and photos, sizes mitigation and rebuild scope, and drafts a detailed restoration estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your restoration scope`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded damage reports, moisture readings, photos, or a scope package. Build a complete restoration estimate. (1) Extract affected areas, mitigation tasks, drying equipment needs, demolition scope, rebuild work, contents handling, and access constraints from the uploaded files. (2) Estimate materials, labor, equipment rental, subcontractor work, and schedule dependencies. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight exclusions, insurance-sensitive items, and field-verification questions that should be confirmed before sending. (5) Deliver a detailed restoration estimate with line-item pricing, scope summary, and next steps that is ready for the customer or carrier review.`,heroOverlaySteps:[`Extracting mitigation scope, rebuild tasks, and access constraints from your files`,`Sizing materials, labor, equipment rental, and subcontractor work`,`Building pricing options with assumptions, alternates, and margin`,`Restoration estimate with scope summary, ready for review and send`],generatingSteps:[`Reading the uploaded damage reports, moisture readings, photos, and scope package`,`Designing an agent to organize mitigation, rebuild, and equipment assumptions`,`Configuring estimate logic for alternates, exclusions, and margin`,`Preparing a detailed restoration estimate with line items and next steps`],featureSectionTitle:`From damage report to estimate-ready pricing`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built around mitigation and rebuild reality`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, photos, moisture logs, and internal review workflows stay connected so estimates and revisions move faster.`,`Mitigation tasks. Equipment assumptions. Rebuild scope. Exclusions. Computer gives your team a restoration estimate draft that is ready for review.`],capabilitySectionTitle:`Your estimator, on autopilot`,capabilitySectionSubtitle:`Upload the scope, get back a restoration estimate built around the real damage and rebuild requirements.`,capabilityCards:[{title:`Scope Extraction`,description:`Computer can extract affected areas, mitigation needs, demolition scope, rebuild tasks, and access issues from damage reports and photos.`},{title:`Materials & Labor Planning`,description:`Computer can size materials, labor, equipment rental, and subcontractor work so the estimate reflects the actual restoration scope.`},{title:`Pricing Options`,description:`Computer can build pricing with assumptions, alternates, exclusions, and margin so your team can move faster from inspection to estimate.`},{title:`Connect Your Tools`,description:`Computer can organize estimate drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your pricing guardrails, estimate structure, and documentation standards across sessions so every quote stays consistent.`},{title:`Change-Order Protection`,description:`Computer can surface scope gaps, insurance-sensitive items, and field-verification needs early so your team can protect margin before approval.`}]});export{t as default};
